package br.com.myfinancehub;

import android.content.ContentProvider;
import android.content.ContentValues;
import android.content.Context;
import android.database.Cursor;
import android.database.MatrixCursor;
import android.net.Uri;
import android.os.ParcelFileDescriptor;
import android.provider.OpenableColumns;

import java.io.File;
import java.io.FileNotFoundException;
import java.io.IOException;
import java.util.UUID;
import java.util.concurrent.TimeUnit;
import java.util.regex.Pattern;

/** Shares only PDFs explicitly generated by the user, through temporary read grants. */
public final class ReportShareProvider extends ContentProvider {
    private static final String DIRECTORY = "reports";
    private static final String DISPLAY_NAME = "MyFinanceHub-relatorio.pdf";
    private static final long MAX_AGE_MILLIS = TimeUnit.HOURS.toMillis(24);
    private static final Pattern FILE_NAME = Pattern.compile(
            "[0-9a-f]{8}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{12}\\.pdf");

    @Override public boolean onCreate() { return true; }

    /** Creates the destination before rendering so concurrent exports never share a filename. */
    public static File newPdfFile(Context context) throws IOException {
        File directory = reportDirectory(context);
        if (!directory.isDirectory() && !directory.mkdirs())
            throw new IOException("Não foi possível preparar o relatório para compartilhar.");
        removeExpiredReports(directory, System.currentTimeMillis());
        for (int attempt = 0; attempt < 10; attempt++) {
            File file = new File(directory, UUID.randomUUID() + ".pdf");
            if (file.createNewFile()) return file;
        }
        throw new IOException("Não foi possível criar o relatório para compartilhar.");
    }

    /** No caller can turn an arbitrary private application file into a shareable URI. */
    public static Uri uriFor(Context context, File file) throws IOException {
        validateFile(context, file);
        return new Uri.Builder().scheme("content").authority(authority(context))
                .appendPath(file.getName()).build();
    }

    @Override public ParcelFileDescriptor openFile(Uri uri, String mode) throws FileNotFoundException {
        if (!"r".equals(mode)) throw new FileNotFoundException("O relatório é somente para leitura.");
        try {
            return ParcelFileDescriptor.open(resolve(uri), ParcelFileDescriptor.MODE_READ_ONLY);
        } catch (IOException | IllegalArgumentException error) {
            FileNotFoundException result = new FileNotFoundException("Relatório indisponível para compartilhar.");
            result.initCause(error);
            throw result;
        }
    }

    @Override public Cursor query(Uri uri, String[] projection, String selection,
                                  String[] selectionArgs, String sortOrder) {
        File file = resolve(uri);
        String[] columns = projection == null
                ? new String[]{OpenableColumns.DISPLAY_NAME, OpenableColumns.SIZE} : projection;
        MatrixCursor result = new MatrixCursor(columns, 1);
        Object[] values = new Object[columns.length];
        for (int index = 0; index < columns.length; index++) {
            if (OpenableColumns.DISPLAY_NAME.equals(columns[index])) values[index] = DISPLAY_NAME;
            else if (OpenableColumns.SIZE.equals(columns[index])) values[index] = file.length();
        }
        result.addRow(values);
        return result;
    }

    @Override public String getType(Uri uri) {
        resolve(uri);
        return "application/pdf";
    }

    @Override public Uri insert(Uri uri, ContentValues values) { throw readOnly(); }
    @Override public int update(Uri uri, ContentValues values, String selection, String[] args) {
        throw readOnly();
    }
    @Override public int delete(Uri uri, String selection, String[] args) { throw readOnly(); }

    private File resolve(Uri uri) {
        Context context = getContext();
        if (context == null || uri == null || !"content".equals(uri.getScheme())
                || !authority(context).equals(uri.getAuthority())
                || uri.getQuery() != null || uri.getFragment() != null
                || uri.getPathSegments().size() != 1)
            throw new IllegalArgumentException("Endereço de relatório inválido.");
        String name = uri.getLastPathSegment();
        if (name == null || !FILE_NAME.matcher(name).matches()
                || !("/" + name).equals(uri.getEncodedPath()))
            throw new IllegalArgumentException("Endereço de relatório inválido.");
        try {
            File file = new File(reportDirectory(context), name);
            validateFile(context, file);
            return file;
        } catch (IOException error) {
            throw new IllegalArgumentException("Relatório indisponível para compartilhar.", error);
        }
    }

    private static File reportDirectory(Context context) throws IOException {
        if (context == null) throw new IOException("Armazenamento indisponível.");
        File directory = new File(context.getCacheDir().getCanonicalFile(), DIRECTORY);
        // A symlink must never broaden the provider's access outside its dedicated cache folder.
        if (!directory.equals(directory.getCanonicalFile()))
            throw new IOException("Pasta de relatórios inválida.");
        return directory;
    }

    private static void validateFile(Context context, File file) throws IOException {
        if (file == null || !FILE_NAME.matcher(file.getName()).matches())
            throw new IOException("Arquivo de relatório inválido.");
        File directory = reportDirectory(context);
        File expected = new File(directory, file.getName());
        if (!file.getAbsoluteFile().equals(expected) || !file.getCanonicalFile().equals(expected)
                || !file.isFile())
            throw new IOException("Arquivo de relatório inválido.");
    }

    private static void removeExpiredReports(File directory, long now) {
        File[] files = directory.listFiles();
        if (files == null) return;
        for (File file : files) {
            long modified = file.lastModified();
            if (!FILE_NAME.matcher(file.getName()).matches() || !file.isFile()
                    || modified <= 0 || modified > now || now - modified <= MAX_AGE_MILLIS) continue;
            try {
                if (file.getCanonicalFile().equals(file.getAbsoluteFile())) file.delete();
            } catch (IOException ignored) {
                // A failed cleanup cannot prevent the user from generating a fresh report.
            }
        }
    }

    private static String authority(Context context) { return context.getPackageName() + ".reports"; }
    private static UnsupportedOperationException readOnly() {
        return new UnsupportedOperationException("Os relatórios compartilhados são somente para leitura.");
    }
}
